static void a0_reply(void){unsigned i;group("full A0 uses actual copy zero and GATT builder over same RAM");deep_fresh();for(i=0;i<19;i++)put(A(0xbf44)+i,0x90+i,1);CHECK(ta_dispatch_deep(&m,0x13160,123)==GB_RETURNED);CHECK(m.deep.memory==&m.memory&&m.deep.frame_offset==8&&m.deep.frame_length==76);CHECK(m.deep.replies==1&&m.replies_committed==1&&m.halted==0);CHECK(get(A(0xb194),1)==0xa0&&get(A(0xb18e),2)==82);for(i=0;i<19;i++){CHECK(m.deep.stack[48+i]==0x90+i);CHECK(m.deep.known[48+i]==255);CHECK(get(A(0xb18c)+11+40+i,1)==0x90+i);}CHECK(m.deep.stack[9]==0&&m.deep.stack[10]==2&&m.deep.stack[11]==1);CHECK(memcmp(m.deep.stack+12,uid,14)==0);}
static void a0_timer_config(void){uint32_t status=9,raw=0,node=0;unsigned i;group("A0 authenticated uses exact ROM96 remaining ticks and fresh shared config OUT copies");deep_fresh();put(A(0xc794),1,1);put(A(0xc29c),8,1);for(i=0;i<16;i++){put(A(0xc298)+i,0xa0+i,1);put(A(0xc2f8)+i,0x60+i,1);}put(A(0xc29c),8,1);CHECK(rc_timer_start(&adapter,3,1,4800,&status)==1&&status==1);CHECK(rc_timer_find(&adapter,3,1,&node)==1&&node!=0);raw_clock=1600;CHECK(rc_timer_remaining(&adapter,3,1,&raw)==1);CHECK(ta_dispatch_deep(&m,0x13160,0)==GB_RETURNED);CHECK(m.replies_committed==1&&m.deep.frame_length==76);CHECK((uint16_t)(m.deep.stack[28]|((uint16_t)m.deep.stack[29]<<8))==(uint16_t)(((raw*UINT32_C(10))>>4)+50));CHECK(memcmp(m.deep.stack+32,m.memory.ram+0xc298,16)==0&&memcmp(m.deep.stack+67,m.memory.ram+0xc2f8,16)==0);}
static void b0_registry(void){uint32_t pending;group("SystemProcess native registry enters full B0 and commits actual 33 byte snapshot");deep_fresh();put(A(0xc794),1,1);put(A(0xc795),1,1);CHECK(tf_schedule(&m.memory,0x135d4,0,0,0x44332211)==0);pending=get(A(0x3094),4);CHECK(ta_system_process(&m)==RK_RETURNED);CHECK(m.deep.entry==0x135d4&&m.deep.argument==0x44332211);CHECK(m.deep.frame_length==33&&m.deep.replies==1&&m.replies_committed==1);CHECK(get(TF_REGISTRY+4,4)==0&&get(TF_REGISTRY+8,4)==0);CHECK(get(pending+6,2)==0&&get(A(0x304c),1)==4);CHECK(get(A(0xb194),1)==0xb0&&get(A(0xb18e),2)==39);CHECK(m.deep.stack[4]&4);}
static void pause_and_masks(void){group("B0 pause returns before ROM calls; missing field mask retains native prefix");deep_fresh();put(A(0xc790),1,1);m.candidate=NULL;CHECK(ta_dispatch_deep(&m,0x135d4,0)==GB_RETURNED);CHECK(m.deep.calls==0&&m.deep.replies==0&&m.deep.frame_length==0);deep_fresh();put(A(0xc248),0,2);m.memory.known[0xc249]=0xbf;CHECK(ta_dispatch_deep(&m,0x135d4,0)==GB_HALT);CHECK(m.deep.boundary_va==0x136cc&&m.deep.needed_mask==0x4000&&m.deep.boundary_address==A(0xc248));CHECK(m.deep.calls==1&&m.deep.known[0]==255&&m.replies_committed==0);}
