int main(int argc,char **argv){FILE *f;unsigned i;if(argc!=3)return 2;f=fopen(argv[1],"rb");if(!f||fread(runtime,1,sizeof(runtime),f)!=sizeof(runtime)){if(f)fclose(f);return 2;}fclose(f);f=fopen(argv[2],"rb");if(!f||fread(boot,1,sizeof(boot),f)!=sizeof(boot)){if(f)fclose(f);return 2;}fclose(f);for(i=0;i<14;i++){uid[i]=(uint8_t)(17+i);known[i]=255;}uid[12]=uid[0];uid[13]=uid[1];a0_reply();a0_timer_config();b0_registry();pause_and_masks();reply_override();primitive_override();candidate_copy_guards();printf("DEEP_BRIDGE_RESULT groups=%u checks=%u failures=%u original_executed=no hardware=no\n",groups,checks,failures);return failures?1:0;}
